import re

COLS = ['name', 'flags', 'level', 'description', 'type', 'alt-type', 'argname', 'default', 'argdef', 'value']
LINE = re.compile(r'^[^:]+:\d+:\d+:[^:]*:\d+:\d+:')

def parse(lines):
    groups = {'name': 'groups', 'kind': 'table', 'lines': [], 'records': []}
    options = {'name': 'options', 'kind': 'table', 'lines': [], 'records': []}
    current = ''
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if not LINE.match(line):
            continue
        parts = line.split(':', 9)
        while len(parts) < 10:
            parts.append('')
        rec = dict(zip(COLS, parts))
        try:
            flags = int(rec['flags'])
        except ValueError:
            flags = 0
        if flags & 1:
            current = rec['name']
            groups['lines'].append(i)
            groups['records'].append(rec)
        else:
            row = {'group': current}
            row.update(rec)
            options['lines'].append(i)
            options['records'].append(row)
    blocks = []
    if groups['records']:
        blocks.append(groups)
    if options['records']:
        blocks.append(options)
    return {'blocks': blocks, 'skip': []}
